import lombok.NoArgsConstructor;

import java.time.LocalDate;

@Entity @jakarta.persistence.Table(name = "point")
@Getter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class Xmt80 extends Xzh80Entity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "user_id")
    private Xjm45 user;

    private int amount;

    private int remainingAmount;

    private String reason;

    private LocalDate expirationDate;

    @Enumerated(EnumType.STRING)
    private Xmt80Status status;


    public Xmt80(Xjm45 user, int amount, String reason) {
        this.user = user;
        this.amount = amount;
        this.remainingAmount = amount;
        this.reason = reason;
        this.expirationDate = LocalDate.now().plusDays(90);
        this.status = Xmt80Status.AVAILABLE;
    }


    public void assignUser(Xjm45 user) {
        this.user = user;
    }

    public void unassignUser() {
        this.user = null;
    }


    public int use(int amountToUse) {
        if (this.status != Xmt80Status.AVAILABLE) {
            return 0;
        }

        if (amountToUse >= this.remainingAmount) {
            int used = this.remainingAmount;
            this.remainingAmount = 0;
            this.status = Xmt80Status.USED;
            return used;
        } else {
            this.remainingAmount -= amountToUse;
            return amountToUse;
        }
    }


    public void expire() {
        if (this.status == Xmt80Status.AVAILABLE) {
            this.status = Xmt80Status.EXPIRED;
            this.remainingAmount = 0;
        }
    }


    public void setReason(String reason) {
        this.reason = reason;
    }


    public boolean isValid() {
        return this.status == Xmt80Status.AVAILABLE &&
                expirationDate.isAfter(LocalDate.now());
    }



    public void setExpirationDate(LocalDate expirationDate) {
        this.expirationDate = expirationDate;
    }




    public void setStatus(Xmt80Status status) {
        this.status = status;
    }
