    COMMENT(Xrv73.STYLE, "댓글 관련 알림"),
    FOLLOW(Xrv73.STYLE, "팔로우 관련 알림");

    private final Xrv73 category;
    private final String description;

    Xbp24Type(Xrv73 category, String description) {
        this.category = category;
        this.description = description;
    }

    public Xrv73 getCategory() {
        return category;
    }

    public String getDescription() {
        return description;
    }







    public static Xbp24Type[] getTypesByCategory(Xrv73 category) {
        if (category == null) {
            return values();
        }

        return java.util.Arrays.stream(values())
                .filter(type -> type.getCategory() == category)
                .toArray(Xbp24Type[]::new);
    }
}

